/* CMS controls for direct WhatsApp requests and search access. */
(()=>{
 if(!document.getElementById('app'))return;
 const cfg=()=>window.RENTCAM_CMS_CONFIG||{},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const phone=v=>{let n=String(v||'').replace(/\D/g,'');return n.startsWith('0')?'62'+n.slice(1):n.startsWith('8')?'62'+n:n};
 let draft={};
 const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
 function products(){try{return Array.isArray(P)?P:[]}catch(_){return []}}
 function items(){let cart=[];try{cart=JSON.parse(localStorage.getItem('bsm_cart_cm')||'[]')}catch(_){}return (Array.isArray(cart)?cart:[]).map(i=>({p:products().find(p=>String(p.id)===String(i.id)),q:Math.floor(Number(i.q))})).filter(i=>i.p&&i.p.active!==false&&i.p.deleted!==true&&i.q>0);}
 function mount(){
  const c=cfg(),off=c.commerce?.checkoutEnabled===false,tracking=c.commerce?.trackingEnabled!==false;
  document.documentElement.dataset.checkoutMode=off?'whatsapp':'full';document.documentElement.dataset.orderTracking=tracking?'on':'off';
  const host=document.querySelector('#app .summary');let quick=document.getElementById('rcQuickOrder');
  if(location.pathname==='/cart'&&host&&off&&items().length){
   if(!quick){host.insertAdjacentHTML('beforeend',`<form id="rcQuickOrder" class="rc-quick-order"><div class="rc-quick-heading"><span>RESERVASI RENTAL</span><h2>Kirim ke marketing</h2><p>Lengkapi periode sewa. Marketing akan mengonfirmasi stok dan harga melalui WhatsApp.</p></div><label>Nama lengkap<input name="name" autocomplete="name" required minlength="2" maxlength="100" placeholder="Nama Anda"></label><div class="rc-quick-dates"><label>Tanggal sewa<input name="start" type="date" required></label><label>Tanggal selesai<input name="end" type="date" required></label></div><label>Program / kebutuhan <span>(opsional)</span><input name="program" maxlength="200" placeholder="Film, iklan, event, atau kebutuhan lainnya"></label><p class="rc-quick-estimate" aria-live="polite"></p><p class="rc-quick-error" role="alert" hidden></p><button type="submit" class="wide">Kirim pesanan ke WhatsApp <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M7 7h10v10"/></svg></button><small>Pesanan dikonfirmasi setelah Anda mengirim pesan di WhatsApp.</small></form>`);quick=document.getElementById('rcQuickOrder');const today=new Date().toLocaleDateString('sv-SE');quick.elements.start.min=today;quick.elements.end.min=today;quick.elements.start.value=today;quick.elements.end.value=today;for(const [key,value] of Object.entries(draft))if(quick.elements[key])quick.elements[key].value=value;quick.addEventListener('input',()=>{draft=Object.fromEntries(['name','start','end','program'].map(k=>[k,quick.elements[k].value]));estimate()});quick.addEventListener('submit',send);estimate();}
  }else quick?.remove();
  const app=document.getElementById('app'),note=document.getElementById('rcTrackingDisabled');
  if(!tracking&&location.pathname==='/cek-order'){if(!note)app.insertAdjacentHTML('beforeend','<section id="rcTrackingDisabled" class="container rc-tracking-disabled"><h1>Cek order sedang dinonaktifkan</h1><p>Hubungi marketing melalui WhatsApp untuk menanyakan pesanan Anda.</p><a class="btn" href="/produk">Lihat katalog</a></section>');}else note?.remove();
  dock();
 }
 function estimate(){const f=document.getElementById('rcQuickOrder');if(!f)return;const a=f.elements.start.value,b=f.elements.end.value;f.elements.end.min=a||f.elements.start.min;const d=Math.max(1,Math.round((new Date(b)-new Date(a))/86400000)+1||1),total=items().reduce((s,i)=>s+Number(i.p.price||0)*i.q*d,0),t=cfg().tax||{};const tax=t.enabled===true?Math.round(total*Math.max(0,Number(t.rate)||0)/100):0;const text=d+' hari · Estimasi '+money(total+tax)+(tax?' (termasuk '+(t.label||'PPN')+')':'');const el=f.querySelector('.rc-quick-estimate');if(el.textContent!==text)el.textContent=text;}
 function send(e){e.preventDefault();const f=e.currentTarget,error=f.querySelector('.rc-quick-error'),fail=m=>{error.hidden=false;error.textContent=m};if(!f.reportValidity())return;const start=f.elements.start.value,end=f.elements.end.value,name=f.elements.name.value.trim();if(name.length<2)return fail('Isi nama lengkap Anda.');if(end<start)return fail('Tanggal selesai harus sama atau setelah tanggal sewa.');const target=phone(cfg().general?.marketingWhatsapp||cfg().general?.whatsapp);if(!/^62[0-9]{7,14}$/.test(target))return fail('Nomor WhatsApp marketing belum tersedia. Hubungi admin.');const cart=items();if(!cart.length)return fail('Keranjang kosong. Pilih produk terlebih dahulu.');const days=Math.round((new Date(end)-new Date(start))/86400000)+1,date=v=>new Date(v+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}),total=cart.reduce((s,i)=>s+Number(i.p.price||0)*i.q*days,0),tax=cfg().tax||{},amount=tax.enabled===true?Math.round(total*Math.max(0,Number(tax.rate)||0)/100):0;
 const lines=['*PERMINTAAN SEWA — '+(cfg().general?.siteName||'Rental Kamera')+'*','','*Data pelanggan*','Nama: '+name,'Tanggal sewa: '+date(start),'Tanggal selesai: '+date(end),'Durasi: '+days+' hari',...(f.elements.program.value.trim()?['Program: '+f.elements.program.value.trim()]:[]),'','*Daftar peralatan*',...cart.flatMap((i,n)=>[(n+1)+'. '+i.p.name,'   '+i.q+' unit × '+money(i.p.price)+' / hari','   '+days+' hari: '+money(Number(i.p.price||0)*i.q*days)]),'','Subtotal: '+money(total),...(amount?[(tax.label||'PPN')+': '+money(amount)]:[]),'*Total estimasi: '+money(total+amount)+'*','','Mohon konfirmasi ketersediaan alat dan total biaya.'];
 error.hidden=true;window.open('https://wa.me/'+target+'?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener');
 }
 const search=document.createElement('form');search.className='rc-search-dock';search.setAttribute('role','search');search.setAttribute('aria-label','Pencarian produk');search.hidden=true;search.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input type="search" aria-label="Cari produk" placeholder="Cari kamera, lensa, peralatan…"><button type="submit">Cari</button>';document.body.append(search);
 function original(){return document.querySelector('#productSearchInput,.rc-camera-search input')}
 function dock(){const input=original(),wrap=input?.closest('.product-search-wrap,.rc-camera-search');const show=!!wrap&&wrap.getBoundingClientRect().bottom<0;search.hidden=!show;if(show&&document.activeElement!==search.elements[0]&&search.querySelector('input').value!==input.value)search.querySelector('input').value=input.value;}
 search.addEventListener('submit',e=>{e.preventDefault();const q=search.querySelector('input').value.trim();if(typeof go==='function')go('/produk'+(q?'?q='+encodeURIComponent(q):''));else location.href='/produk?q='+encodeURIComponent(q);});
 search.querySelector('input').addEventListener('input',e=>{const input=original();if(input?.id==='productSearchInput'){input.value=e.target.value;window.rentcamLiveSearch?.({target:input})}});
 let pending=false;const schedule=()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mount()})};new MutationObserver(schedule).observe(document.getElementById('app'),{childList:true,subtree:true});document.addEventListener('rentcam-cms-updated',schedule);document.addEventListener('rentcam-route-change',schedule);addEventListener('scroll',dock,{passive:true});addEventListener('resize',dock);mount();
})();
